SELECT AVG(total_order_value) AS average_order_value FROM (
  SELECT O.Order_ID, SUM(I.Sales) AS total_order_value
  FROM Orders O
  JOIN Order_Items I ON O.Order_ID = I.Order_ID
  GROUP BY O.Order_ID
) AS per_order; | SELECT COUNT(DISTINCT O.Order_ID) AS order_count FROM Orders O;

SELECT COUNT(DISTINCT O.Order_ID) AS Same_Day_Orders
FROM Orders O
WHERE O.Ship_Mode LIKE '%Same Day%';
